Algorithm Voting
  Define votes As Dictionary<String, Integer> <- dictionary();
  Define name As String;
  Read name;
  While name <> "end" Do
    Switch votes.find(name) Do
      Some(count): votes[name] <- count + 1;
      None: votes[name] <- 1;
    EndSwitch
    Read name;
  EndWhile
  Define winner As String <- "";
  Define highest As Integer <- 0;
  For Each candidate In votes.keys() Do
    If votes[candidate] > highest Or (votes[candidate] = highest And candidate < winner) Then
      winner <- candidate;
      highest <- votes[candidate];
    EndIf
  EndFor
  If highest = 0 Then
    Write "No votes";
  Else
    Write winner, " ", highest;
  EndIf
EndAlgorithm
